import React, { Component } from 'react';
import {Link } from 'react-router-dom';
import { Tabs,Card,Table ,Button} from 'antd';
// import {transactionGet,GetTradeData} from '../../services/Api';
// import { trackPromise } from 'react-promise-tracker';
import ProductModal from '../Modals/ProductModal';

const { TabPane } = Tabs;

function callback(key) {
	console.log(key);
  }

class Products extends Component {	
    constructor(props){
        super(props)
		this.state = {
			order:'',
            transactions:[],
            visible:false,
	};

    this.ViewTransaction=()=>{
        props.history.push("/viewtransactions");
    };
    this.saveFormRef = (formRef) =>  this.formRef = formRef;
    this.handleCancel = (e) => this.setState({ visible: false,error:false,paymentModalVisible:false});
    this.handleCreate = () => {

        const form = this.formRef.props.form;
    form.validateFields( async(err, values) => {
     let ReceiverWalletaddress= values.address;
     let SenderWalletAddress =values.wallet;
     let Amount =values.amount;


    });
  };
    }  




	async componentDidMount(){		   
        // trackPromise(
		// 	this.getTransactionData().then(result=>{

		// 	  this.setState({ 
		// 		transactions:result.data,
		// 	})
		// 	}	
		// 	)

		//   )
		//   this.getTradeData();
	}

	// async getTransactionData(){
	// 	const Transactions= await transactionGet();
	// 	// console.log(Transactions.data);
	// 	return Transactions;
	// }

	// async getTradeData(){
	// 	const TradeData= await GetTradeData();

	// 	console.log(TradeData.data);
    // }


	render() {
        const total = this.state.transactions.length;
        const limit = 10;
        const columns = [
            {title: 'Date', dataIndex: 'createdAt', key: 'createdAt', width:105, 
            },
			{title: 'Name', dataIndex: 'name', key: 'name', 
				render: (text,record) =><Link to={'/viewtransactions/'}><a style={{color:'green'}}>{text} </a></Link> ,
			},
			{title: 'Quantity', dataIndex: 'quantity', key: 'quantity', },	
			{title: 'Price ', dataIndex: 'price', key: 'price', },
            {title: ' Vendor Name ', dataIndex: 'vendorname', key: 'vendorname', },
            {title: ' Vendor Phone ', dataIndex: 'vendorphone', key: 'vendorphone', }
		];
	return (
			<div>

             <div style={{float: 'right',paddingBottom:20}}>
                <Button type='primary'>
                    Add Product
                </Button>
                </div>
			    <div className="table-responsive">
					<Table bordered  columns={columns} dataSource={this.state.transactions} className="cardtable" onChange={this.paginationFun} scroll={{ x: 1200 }} rowKey="id" pagination={{size:'small', total:total, pageSize: limit, showTotal:total => `Total ${total} Transactions`}}
					/>
				</div> 

                <ProductModal wrappedComponentRef={this.saveFormRef} visible={this.state.visible} onCancel={this.handleCancel} onCreate={this.handleCreate} />
			</div>
		);
	}
}
export default(Products);
